"""Native polygonal imperial vessel and Nell's Lightbearer manifestation. No raster inputs."""
from pathlib import Path
import math
ROOT=Path(__file__).resolve().parents[2];ART=ROOT/'public/art/vector/chapter-six';ART.mkdir(parents=True,exist_ok=True)
INK='#203340';SHADOW='#506b80';BLUE='#819aa8';MARBLE='#e4e5d9';WHITE='#fff0c7';GOLD='#c89b53';RUST='#a35c42';LIGHT='#b3dad0'
def p(points,c):return '<polygon points="'+' '.join(f'{x:g},{y:g}'for x,y in points)+f'" fill="{c}"/>'
def r(x,y,w,h,c):return f'<path d="M{x:g} {y:g}h{w:g}v{h:g}h{-w:g}Z" fill="{c}"/>'
def l(points,c,w=3):return '<polyline points="'+' '.join(f'{x:g},{y:g}'for x,y in points)+f'" fill="none" stroke="{c}" stroke-width="{w}"/>'
def ring(cx,cy,rx,ry,c,w=8):return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}" fill="none" stroke="{c}" stroke-width="{w}"/>'
def vessel(pose='idle'):
 charged=pose in ('charge','cast');fallen=pose=='fallen';out=[]
 def m(points):return [(528-x,y)for x,y in points]
 # Stepped throne architecture and deep recesses, rather than a flat gold crown.
 out += [p([(143,110),(151,54),(207,54),(224,31),(250,31),(264,9),(279,31),(305,31),(322,54),(377,54),(385,110),(346,155),(182,155)],'#91774c'),p([(156,99),(163,64),(216,64),(232,41),(255,41),(264,25),(274,41),(297,41),(313,64),(366,64),(372,99)],GOLD),p([(178,94),(183,72),(224,72),(237,50),(291,50),(305,72),(346,72),(351,94),(326,128),(202,128)],SHADOW),p([(213,79),(227,62),(301,62),(315,79),(315,155),(213,155)],'#162d38')]
 for x in (170,204,324,358):out += [r(x-4,70,8,69,BLUE),r(x-4,69,4,67,WHITE)]
 # Lower body remains a substantial throne base, with cloth between rigid armor planes.
 out += [p([(172,174),(356,174),(384,249),(353,268),(175,268),(144,249)],'#4c6673'),p([(181,182),(347,182),(365,241),(343,251),(185,251),(164,241)],BLUE),p([(213,180),(315,180),(332,251),(298,260),(264,251),(230,260),(195,251)],'#345364'),p([(230,187),(250,190),(241,248),(228,251)],SHADOW),p([(278,189),(298,186),(307,249),(290,252)],SHADOW)]
 # Each shoulder connects through an elbow to a broad articulated hand.
 for flip in (False,True):
  def q(points):return m(points)if flip else points
  out += [p(q([(91,135),(137,126),(172,168),(161,205),(131,223),(100,204),(74,178)]),'#4a6470'),p(q([(99,142),(131,136),(158,170),(151,194),(129,207),(109,191),(86,175)]),BLUE),p(q([(99,142),(113,145),(137,180),(129,207),(109,191),(86,175)]),SHADOW),p(q([(115,184),(143,177),(159,194),(147,213),(124,224),(106,209)]),GOLD),p(q([(83,112),(130,83),(199,113),(186,153),(139,168),(80,150),(60,133)]),'#7e969c'),p(q([(85,119),(132,94),(187,117),(177,144),(139,155),(86,141),(72,132)]),MARBLE),p(q([(132,94),(187,117),(177,144),(161,143),(165,120)]),BLUE),p(q([(85,119),(132,94),(165,120),(141,127)]),WHITE),l(q([(78,131),(140,147),(178,136)]),GOLD,5)]
  # Parallel finger plates read as a hand, not disconnected decorative spikes.
  out += [p(q([(104,205),(132,211),(141,235),(124,252),(93,251),(73,236),(77,218)]),'#9b783f'),p(q([(105,214),(124,217),(130,234),(120,243),(96,242),(82,232),(86,223)]),GOLD),p(q([(89,221),(100,217),(118,225),(121,236),(99,231)]),WHITE),l(q([(88,231),(99,234),(102,243)]),'#9b783f',3),l(q([(102,230),(112,233),(115,244)]),'#9b783f',3),p(q([(125,212),(142,207),(151,214),(144,229),(132,233)]),GOLD)]
 # Recessed human head and a wide collar. Flesh has separate brow, nose and jaw planes.
 out += [p([(177,128),(216,112),(240,128),(286,128),(313,111),(352,128),(364,183),(336,211),(192,211),(164,183)],'#7b959b'),p([(184,134),(215,122),(237,140),(289,140),(315,122),(345,134),(353,180),(329,199),(199,199),(176,180)],MARBLE),p([(315,122),(345,134),(353,180),(329,199),(313,185),(320,151)],BLUE),p([(184,134),(215,122),(237,140),(224,151),(191,146)],WHITE),l([(190,162),(215,166),(226,153)],GOLD,4),l([(338,162),(313,166),(302,153)],GOLD,4)]
 face=[p([(243,77),(251,68),(276,68),(286,79),(284,106),(274,122),(253,117),(243,103)],'#766759'),p([(247,79),(255,73),(273,73),(281,82),(279,103),(271,115),(255,111),(248,100)],'#b99a78'),p([(265,74),(274,74),(281,82),(279,103),(271,115),(265,109),(268,96)],'#836d5b'),p([(248,80),(257,75),(262,84),(250,89)],'#d3b795'),p([(258,89),(266,87),(270,102),(261,103)],'#d3b795'),l([(255,108),(268,111),(274,106)],'#584f48',3)]
 if fallen:face += [l([(249,92),(258,94)],INK,3),l([(272,94),(279,92)],INK,3)]
 else:face += [p([(248,86),(261,87),(260,91),(249,90)],INK),p([(269,87),(281,84),(280,89),(270,91)],INK),r(252,92,4,3,INK),r(273,92,4,3,INK)]
 out += ['<g transform="translate(0 '+('6'if fallen else '0')+')">',*face,p([(239,78),(239,54),(250,65),(263,45),(276,64),(289,53),(290,77),(273,83),(254,83)],GOLD),p([(244,73),(251,70),(263,56),(275,70),(285,69),(285,75),(272,78),(254,78)],WHITE),'</g>']
 # The imperial sun is a tangible embossed insignia, not the Benefactor's hollow head.
 out += ['<g id="imperial-sun-insignia">',p([(221,146),(264,135),(307,146),(313,190),(289,225),(264,235),(239,225),(215,190)],'#806b48'),p([(226,150),(264,141),(302,150),(307,188),(285,218),(264,226),(243,218),(221,188)],'#9b783f')]
 cx,cy=264,181
 for i in range(12):
  a=math.radians(i*30-90);ux,uy=math.cos(a),math.sin(a);vx,vy=-uy,ux
  out += [p([(cx+ux*23+vx*5,cy+uy*23+vy*5),(cx+ux*37+vx*3,cy+uy*37+vy*3),(cx+ux*40-vx*2,cy+uy*40-vy*2),(cx+ux*23-vx*5,cy+uy*23-vy*5)],SHADOW if fallen else GOLD if i%2 else WHITE)]
 out += [p([(243,168),(253,157),(275,157),(285,168),(285,191),(274,203),(253,203),(243,191)],'#927444'),p([(247,170),(256,162),(272,162),(280,170),(280,188),(271,198),(256,198),(247,188)],SHADOW if fallen else GOLD),p([(250,171),(257,166),(271,166),(277,172),(273,182),(261,185),(250,181)],BLUE if fallen else WHITE),p([(257,181),(265,173),(273,181),(265,194)],'#29434d'if fallen else LIGHT if not charged else '#eff4d5'),'</g>']
 for y in (250,263):out += [p([(167,y),(214,y-10),(264,y-4),(314,y-10),(361,y),(351,y+8),(306,y+1),(264,y+7),(222,y+1),(177,y+8)],GOLD if not fallen else SHADOW)]
 if fallen:out += [p([(259,144),(266,159),(260,177),(271,187),(260,217),(262,197),(252,183),(260,163)],INK)]
 if pose=='cast':
  for x in (112,203,325,416):out += [p([(x,181),(x+5,197),(x,239),(x-5,199)],WHITE)]
 return out

def lightbearer(pose='idle'):
 out=[];opened=pose=='resist';dy=-3 if pose=='rise'else 0
 # Broken triangular rays, asymmetrical cloth-like planes: a mortal vessel, no god body.
 out += [ring(264,111,96,86,'#9b783f',16),ring(264,111,95,86,GOLD,8)]
 for i in range(11):
  a=math.radians(204+i*27);x=264+math.cos(a)*105;y=111+math.sin(a)*94
  out += [p([(x+math.sin(a)*9,y-math.cos(a)*9),(264+math.cos(a)*139,111+math.sin(a)*125),(x-math.sin(a)*9,y+math.cos(a)*9)],GOLD)]
 for side in [-1,1]:
  def m(pts):return [(264+side*(x-264),y+dy)for x,y in pts]
  out += [p(m([(246,124),(209,102),(170,114),(156,151),(122,171),(97,237),(148,218),(189,199),(211,237),(238,207)]),'#718a96'),p(m([(242,130),(208,115),(181,122),(170,157),(139,178),(119,218),(155,202),(194,184),(214,218),(236,195)]),MARBLE),p(m([(208,115),(213,163),(194,184),(155,202),(176,165),(181,122)]),BLUE),p(m([(242,130),(236,195),(214,218),(211,170)]),GOLD)]
 out += [p([(235,183),(264,169),(295,183),(310,254),(281,239),(264,274),(245,243),(215,256)],SHADOW),p([(240,189),(264,179),(289,190),(296,239),(278,227),(264,255),(249,231),(229,242)],BLUE)]
 # Nell: copper hair, two braids, orange work jacket, full connected limbs.
 out += [p([(247,91),(253,81),(272,82),(282,94),(279,112),(269,122),(252,115)],'#8e6349'),p([(251,93),(257,87),(271,88),(277,96),(274,109),(267,116),(255,111)],'#d6b18c'),p([(248,92),(252,80),(268,78),(280,87),(281,99),(270,91),(261,92),(255,99)],'#a96040'),p([(249,104),(254,108),(253,132),(248,144),(244,139),(248,121)],'#a96040'),p([(277,104),(281,108),(282,129),(287,140),(283,145),(276,132)],'#8c5039'),p([(253,118),(269,118),(280,126),(280,160),(269,168),(250,164),(245,137)],RUST),p([(253,122),(260,128),(259,158),(249,161),(248,138)],'#d29354'),p([(259,159),(275,159),(280,187),(270,191),(265,170),(259,191),(250,188)],'#344f60'),p([(250,166),(257,166),(257,188),(250,190)],SHADOW),p([(270,166),(275,166),(280,185),(273,189)],BLUE),p([(249,186),(258,186),(260,194),(247,194)],'#80553d'),p([(273,185),(280,184),(285,191),(274,194)],'#80553d')]
 out += [r(254,101,4,3,INK),r(270,101,4,3,INK),l([(265,104),(263,108),(267,109)],'#976c51',2),r(260,113,8,2,'#8d5645')]
 # Her anatomical right arm is on screen-left; it closes the lantern during resistance.
 hand=142 if opened else 163
 out += [p([(247,126),(241,128),(233,143),(237,hand),(244,hand),(241,146),(253,136)],RUST),p([(278,125),(286,133),(290,151),(284,156),(278,145),(271,138)],RUST),p([(237,hand-3),(243,hand-3),(244,hand+3),(238,hand+4)],'#d6b18c'),l([(238,hand+3),(238,hand+10)],GOLD,3),r(229,hand+10,17,22,'#9b783f'),r(232,hand+13,11,14,SHADOW if opened else WHITE),r(229,hand+31,17,3,GOLD)]
 if pose=='cast':out += [p([(238,hand+19),(211,205),(173,252),(226,228),(237,hand+22),(283,232),(344,251),(267,191)],WHITE)]
 if opened:out += [p([(220,152),(229,165),(217,198),(206,206)],WHITE),p([(304,142),(310,161),(319,194),(309,179)],WHITE)]
 return out

def support(opened=False):
 if opened:return [p([(5,143),(18,130),(72,130),(91,143),(77,159),(17,159)],SHADOW),p([(18,139),(29,130),(72,134),(79,144),(27,149)],MARBLE),p([(28,131),(32,109),(47,117),(49,137)],BLUE),p([(54,134),(64,117),(79,126),(73,142)],GOLD),r(31,143,37,5,SHADOW)]
 return [p([(5,143),(16,31),(48,5),(80,31),(91,143),(77,159),(17,159)],'#718a96'),p([(17,139),(25,37),(48,19),(70,38),(79,139),(68,147),(28,147)],MARBLE),p([(48,19),(70,38),(79,139),(60,142),(58,45)],BLUE),r(33,57,27,63,INK),r(39,61,15,51,SHADOW if opened else LIGHT),p([(22,37),(48,27),(73,38),(69,46),(48,37),(26,45)],GOLD),r(20,130,57,8,GOLD)]

def write(key,w,h,body):
 (ART/f'{key}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><title>{key.replace("-"," ")}</title>'+''.join(body)+'</svg>\n')
for name,fn,poses in [('imperial',vessel,['idle','charge','cast','fallen']),('lightbearer',lightbearer,['idle','rise','cast','resist'])]:
 for pose in poses:write(name+'-'+pose,528,280,fn(pose))
 portrait=ART/f'{name}-portrait.svg'
 if not portrait.exists():portrait.write_text('<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128"><title>'+name+'</title>'+r(0,0,128,128,INK)+'<g transform="translate(-150 -8) scale(.8)">'+''.join(fn())+'</g></svg>\n')
write('imperial-support',96,160,support());write('imperial-support-broken',96,160,support(True))
print('Exported imperial vessel, supports and Lightbearer poses.')
